/**
 * VoidZone Cloudflare Worker entry (thin router).
 * ALL API logic lives in functions/api/*.js (single source of truth, shared with Cloudflare Pages).
 * This file only serves the embedded frontend and dispatches /api/* to those handlers.
 */
import * as auth from "./functions/api/auth.js";
import * as bookings from "./functions/api/bookings.js";
import * as cashDrawer from "./functions/api/cash-drawer.js";
import * as ccboot from "./functions/api/ccboot.js";
import * as cms from "./functions/api/cms.js";
import * as health from "./functions/api/health.js";
import * as inventory from "./functions/api/inventory.js";
import * as masterLog from "./functions/api/master-log.js";
import * as owner from "./functions/api/owner.js";
import * as wallet from "./functions/api/wallet.js";

const HTML_BASE64 = "";

const BLOCKED_ASSET_PATHS = new Set([
  "/schema.sql", "/wrangler.toml", "/wrangler.jsonc",
  "/package.json", "/package-lock.json", "/worker.js",
  "/auth.js", "/bookings.js", "/readme.md"
]);

let cachedHtml = null;

function getHtmlContent() {
  if (cachedHtml) return cachedHtml;
  const bin = atob(HTML_BASE64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  cachedHtml = new TextDecoder("utf-8").decode(bytes);
  return cachedHtml;
}

const ROUTES = {
  "/api/auth": auth, "/api/bookings": bookings, "/api/cash-drawer": cashDrawer, "/api/ccboot": ccboot,
  "/api/cms": cms, "/api/health": health, "/api/inventory": inventory, "/api/master-log": masterLog,
  "/api/owner": owner, "/api/wallet": wallet
};
const HANDLER = { GET: "onRequestGet", POST: "onRequestPost", OPTIONS: "onRequestOptions" };

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "") || "/";

    if (path.startsWith("/api/")) {
      const mod = ROUTES[path];
      const fn = mod && mod[HANDLER[request.method]];
      if (!fn) {
        return new Response(JSON.stringify({ ok: false, error: mod ? "METHOD_NOT_ALLOWED" : "API route not found" }), {
          status: mod ? 405 : 404, headers: { "Content-Type": "application/json;charset=UTF-8" }
        });
      }
      return fn({ request, env, ctx });
    }

    if (env?.ASSETS && !BLOCKED_ASSET_PATHS.has(path.toLowerCase())) {
      try {
        const assetRes = await env.ASSETS.fetch(request);
        if (assetRes && assetRes.status < 400) return assetRes;
      } catch (err) { /* fall through to embedded HTML */ }
    }

    return new Response(getHtmlContent(), {
      status: 200,
      headers: {
        "Content-Type": "text/html;charset=UTF-8",
        "Cache-Control": "public, max-age=3600",
        "X-Frame-Options": "SAMEORIGIN",
        "X-Content-Type-Options": "nosniff",
        "Referrer-Policy": "strict-origin-when-cross-origin"
      }
    });
  }
};
